INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (102301, 0.0, 24001, 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", "2030/12/17 14:59:59", "アヤネ", 0.0, "2020/07/31 12:00:00", 0.0, 2, 24, 401, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (102301, 0.0, 24002, 1, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", "2030/12/17 14:59:59", "アヤネ", 0.0, "2020/07/31 12:00:00", 2.21, 2, 24, 402, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (102301, 0.0, 24003, 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", "2030/12/17 14:59:59", "アヤネ", 0.0, "2020/07/31 12:00:00", 0.0, 2, 24, 403, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192201, 0.0, 24004, 2, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", "2030/12/17 14:59:59", "アサヒ", 0.0, "2020/07/31 12:00:00", 1.99, 1, 24, 701, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192201, 0.0, 24005, 1, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", "2030/12/17 14:59:59", "アサヒ", 0.0, "2020/07/31 12:00:00", 2.21, 2, 24, 702, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192201, 0.0, 24006, 2, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", "2030/12/17 14:59:59", "アサヒ", 0.0, "2020/07/31 12:00:00", 3.33, 1, 24, 703, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192301, 0.0, 24007, 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", "2030/12/17 14:59:59", "部員３", 0.0, "2020/07/31 12:00:00", 0.0, 2, 24, 801, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192301, 0.0, 24008, 1, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", "2030/12/17 14:59:59", "部員３", 0.0, "2020/07/31 12:00:00", 2.68, 2, 24, 802, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192301, 0.0, 24009, 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", "2030/12/17 14:59:59", "部員３", 0.0, "2020/07/31 12:00:00", 0.0, 2, 24, 803, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192501, 0.0, 24010, 1, "やった！", "2030/12/17 14:59:59", "", 0.0, "2020/07/31 12:00:00", 0.0, 1, 24, 501, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192501, 0.0, 24011, 1, "勝ったよ！", "2030/12/17 14:59:59", "", 0.0, "2020/07/31 12:00:00", 0.0, 1, 24, 502, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192501, 0.0, 24012, 1, "いい調子！", "2030/12/17 14:59:59", "", 0.0, "2020/07/31 12:00:00", 0.0, 1, 24, 503, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, 0.0, 24013, 6, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 5.33, 2, 24, 111, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, 0.0, 24014, 1, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 6.85, 2, 24, 112, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, 0.0, 24015, 1, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 3.0, 2, 24, 113, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192401, 0.0, 24016, 1, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", "2030/12/17 14:59:59", "ダイチ", 0.0, "2020/07/31 12:00:00", 6.11, 2, 24, 611, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192401, 0.0, 24017, 1, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", "2030/12/17 14:59:59", "ダイチ", 0.0, "2020/07/31 12:00:00", 6.75, 2, 24, 612, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192401, 0.0, 24018, 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", "2030/12/17 14:59:59", "ダイチ", 0.0, "2020/07/31 12:00:00", 0.0, 2, 24, 613, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113401, 0.0, 24019, 2, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", "2030/12/17 14:59:59", "ハツネ", 0.0, "2020/07/31 12:00:00", 4.52, 1, 24, 211, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113401, 0.0, 24020, 2, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", "2030/12/17 14:59:59", "ハツネ", 0.0, "2020/07/31 12:00:00", 3.89, 1, 24, 212, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113401, 0.0, 24021, 1, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", "2030/12/17 14:59:59", "ハツネ", 0.0, "2020/07/31 12:00:00", 13.49, 2, 24, 213, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (106501, 0.0, 24022, 1, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", "2030/12/17 14:59:59", "カヤ", 0.0, "2020/07/31 12:00:00", 3.17, 2, 24, 311, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (106501, 0.0, 24023, 1, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", "2030/12/17 14:59:59", "カヤ", 0.0, "2020/07/31 12:00:00", 4.42, 2, 24, 312, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (106501, 0.0, 24024, 6, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", "2030/12/17 14:59:59", "カヤ", 0.0, "2020/07/31 12:00:00", 2.89, 1, 24, 313, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (102301, 0.0, 24025, 4, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", "2030/12/17 14:59:59", "アヤネ", 0.0, "2020/07/31 12:00:00", 3.71, 3, 24, 421, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192201, 0.0, 24026, 2, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", "2030/12/17 14:59:59", "アサヒ", 0.0, "2020/07/31 12:00:00", 5.1, 1, 24, 721, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192301, 0.0, 24027, 1, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", "2030/12/17 14:59:59", "部員３", 0.0, "2020/07/31 12:00:00", 4.34, 3, 24, 821, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (192501, 0.0, 24028, 1, "いい勝負だったよ\nまたやろうね", "2030/12/17 14:59:59", "", 0.0, "2020/07/31 12:00:00", 0.0, 1, 24, 521, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, -360.0, 24029, 1, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 5.62, 2, 24, 101, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, -360.0, 24030, 1, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 9.58, 2, 24, 102, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, -360.0, 24031, 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 0.0, 2, 24, 103, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, -360.0, 24032, 2, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 9.13, 1, 24, 104, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113501, -360.0, 24033, 1, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", "2030/12/17 14:59:59", "ミサト", 0.0, "2020/07/31 12:00:00", 8.27, 2, 24, 105, 10046);
